def eval_expression(expr: str) -> float:
    """
    Evaluate a mathematical expression string supporting +, -, *, /, parentheses,
    and negative numbers, following standard order of operations.

    Raises ZeroDivisionError if division by zero occurs.
    """
    # Tokenize the expression
    tokens = _tokenize(expr)
    # Parse and evaluate
    pos = 0

    def parse_expression():
        nonlocal pos
        result = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        nonlocal pos
        result = parse_factor()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                result /= right
        return result

    def parse_factor():
        nonlocal pos
        # Handle unary plus or minus
        if pos < len(tokens) and tokens[pos] == '-':
            pos += 1
            return -parse_factor()
        if pos < len(tokens) and tokens[pos] == '+':
            pos += 1
            return parse_factor()

        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")

        token = tokens[pos]

        if token == '(':
            pos += 1
            result = parse_expression()
            if pos >= len(tokens) or tokens[pos] != ')':
                raise ValueError("Expected closing parenthesis")
            pos += 1
            return result

        # It should be a number
        try:
            value = float(token)
            pos += 1
            return value
        except ValueError:
            raise ValueError(f"Invalid token: {token}")

    result = parse_expression()
    if pos != len(tokens):
        raise ValueError("Unexpected token after expression: " + str(tokens[pos]))
    return result


def _tokenize(expr: str) -> list:
    """Tokenize the expression into numbers, operators, and parentheses."""
    tokens = []
    i = 0
    expr = expr.replace(' ', '')
    while i < len(expr):
        ch = expr[i]
        if ch in '+-*/()':
            tokens.append(ch)
            i += 1
        elif ch.isdigit() or ch == '.':
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            tokens.append(expr[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {ch}")
    return tokens
